def f(xs):
    # Apply chunk operation with k=3
    chunks = [xs[i:i+3] for i in range(0, len(xs), 3)]

    # Apply prune operation to remove negative elements
    pruned_chunks = []
    for chunk in chunks:
        if all(x >= 0 for x in chunk):
            pruned_chunks.append(chunk)

    # Flatten the pruned chunks back into a single list
    return [item for sublist in pruned_chunks for item in sublist]

